-- GENERATED by tools/gen_townsfolk.py. Hearthgate townsfolk (roadmap P3): walks about, talks to itself, gives a tip.
local npcName = "Corwin the Minstrel"
local npcType = Game.createNpcType(npcName)
local npcConfig = {}
npcConfig.name = npcName
npcConfig.description = "a minstrel who sings of climbers past"
npcConfig.health = 100
npcConfig.maxHealth = npcConfig.health
npcConfig.walkInterval = 2000
npcConfig.walkRadius = 2
npcConfig.outfit = { lookType = 128, lookHead = 114, lookBody = 94, lookLegs = 79, lookFeet = 76, lookAddons = 1 }
npcConfig.flags = { floorchange = false }
-- G12 (Grok session 3): six townsfolk at one line per ~57 s each filled the square's chat; now about one every 3 minutes each
npcConfig.voices = {
	interval = 45000,
	chance = 25,
	{ text = "*strums* Oh the tower stands so tall and grey..." },
	{ text = "A copper for a song? No? A song anyway!" },
	{ text = "*hums a tune about the Gate Hound*" },
}

local TIPS = {
	"The Floor Beacon by the Hearth: light a fire bowl and everyone on the floor hunts better for an hour.",
	"The Monument by the Hearth carries the names of those who opened each floor. Be the next!",
	"Every arena event crowns a champion. Their statue stands right here by the fountain.",
}

local keywordHandler = KeywordHandler:new()
local npcHandler = NpcHandler:new(keywordHandler)
npcType.onThink = function(npc, interval)
	npcHandler:onThink(npc, interval)
end
npcType.onAppear = function(npc, creature) npcHandler:onAppear(npc, creature) end
npcType.onDisappear = function(npc, creature) npcHandler:onDisappear(npc, creature) end
npcType.onMove = function(npc, creature, from, to) npcHandler:onMove(npc, creature, from, to) end
npcType.onSay = function(npc, creature, type, message) npcHandler:onSay(npc, creature, type, message) end
npcType.onCloseChannel = function(npc, player) npcHandler:onCloseChannel(npc, player) end

local function greet(npc, player)
	npcHandler:say(TIPS[math.random(#TIPS)], npc, player)
	return true
end

local function creatureSayCallback(npc, player, type, msg)
	if not npcHandler:checkInteraction(npc, player) then
		return false
	end
	if SpireHunt and MsgContains(msg, "hunt") then
		npcHandler:say(SpireHunt.advice(player:getLevel()), npc, player)
		return true
	end
	if SpireRumours and SpireRumours.talk(npc, npcHandler, player, msg, npcName) then
		return true -- adventure layer 4.7: one rumour a day
	end
	return greet(npc, player)
end

npcHandler:setMessage(MESSAGE_GREET, "Oh, hello |PLAYERNAME|! Want a {tip}? Or ask me where to {hunt}, or for a {rumour}.")
npcHandler:setMessage(MESSAGE_FAREWELL, "Off you go, then!")
npcHandler:setCallback(CALLBACK_MESSAGE_DEFAULT, creatureSayCallback)
npcHandler:addModule(FocusModule:new(), npcConfig.name, true, true, true)
npcType:register(npcConfig)
